        let b = bridge(true);
        b.import_session(session("synthetic-owner"))
            .await
            .unwrap_or_else(|_| panic!("draft binding import"));
        let barrier = Arc::new(DraftReturnBarrier::default());
        *b.state
            .draft_return_barrier
            .lock()
            .unwrap_or_else(|_| panic!("draft barrier")) = Some(barrier.clone());
        // Observe the existing bridge authority through its supported guard;
        // Registry's private epoch is owned by the essential module.
        let proof_guard = EssentialGuard::new(&b, false)
            .unwrap_or_else(|_| panic!("draft live bridge guard"));
        let identity = b.state.identity_epoch.load(Ordering::Acquire);
        let other = b.clone();
        let call = tokio::spawn(async move { other.drafts_sync().await });
        barrier.completed.notified().await;
        // Exact core hook used by authoritative failed validate_session; unlike
        // import/cancel, this intentionally leaves bridge epochs unchanged.
        b.state.client.lock().await.forget_session();
        assert!(proof_guard.check().is_ok(), "core revocation must leave the old bridge guard live");
        assert_eq!(identity, b.state.identity_epoch.load(Ordering::Acquire));
        barrier.resume.notify_one();
        let error = call
            .await
            .unwrap_or_else(|_| panic!("draft task"))
            .err()
            .unwrap_or_else(|| panic!("revoked draft output released"));
        assert_eq!(error.code, "authentication");
        assert!(barrier.wiped.load(Ordering::Acquire));
        assert!(proof_guard.check().is_ok(), "the completed return must fail on core authority, not bridge cancellation");
        assert_eq!(identity, b.state.identity_epoch.load(Ordering::Acquire));
        // This observer admits one independent work item. Drop it before the
        // original cleanup assertion so only the call's registry cleanup counts.
        drop(proof_guard);
        assert!(
            b.state
                .work_operations
                .lock()
                .unwrap_or_else(|_| panic!("draft work"))
                .is_empty()
        );
    }
}

//! Explicit Cookie version-content delegation; no CLI/credential discovery.
// contract-test: supporting surface=sdks.rust assertions=sdk.library.explicit-headless,sdk.encryption.local-only,auth.session.authoritative-enforcement
use super::{work::work_authority, *};
use zeroize::Zeroize;
pub(super) fn wipe(value: &mut Value) {
    match value {
        Value::String(s) => s.zeroize(),
        Value::Array(a) => {
            for v in a {
                wipe(v)
            }
        }
        Value::Object(o) => {
            for (mut key, mut v) in std::mem::take(o) {
                key.zeroize();
                wipe(&mut v)
            }
        }
        _ => {}
    }
    *value = Value::Null;
}
struct Pending(Value);
impl Drop for Pending {
    fn drop(&mut self) {
        wipe(&mut self.0)
    }
}
impl SessionBridge {
    pub async fn embeds_version_content(&self, id: String, version_json: String) -> Result<String> {
        if id.len() != 36 || version_json.len() > 128 {
            return Err(
                Error::Invalid("A full embed ID and safe integer version are required.").into(),
            );
        }
        let version: i64 = serde_json::from_str(&version_json)
            .map_err(|_| BindingError::from(Error::Invalid("Invalid integer version.")))?;
        let guard = Arc::new(self.admit_work()?);
        let worker_guard = guard.clone();
        let state = self.state.clone();
        let joined = self
            .transaction(async move {
                let mut client = Self::live_client(&state).await?;
                work_authority(&worker_guard)?;
                client.set_operation_cancel(worker_guard.token());
                let result = client
                    .embed_version_content_with_admission(&id, version)
                    .await;
                let (value, admission) = match result {
                    Ok(value) => value,
                    Err(error) => {
                        client.set_operation_cancel(CancellationToken::new());
                        return Err(BindingError::from(error));
                    }
                };
                let value = Pending(value);
                let output = Zeroizing::new(
                    serde_json::to_string(&value.0)
                        .map_err(|_| BindingError::from(Error::Protocol))?,
                );
                if output.len() > 64 * 1024 * 1024 {
                    return Err(Error::Invalid("Version output exceeds the supported size.").into());
                }
                work_authority(&worker_guard)?;
                admission.check(&client).map_err(BindingError::from)?;
                Ok((output, admission))
            })
            .await;
        if let Err(error) = work_authority(&guard) {
            if let Ok((mut output, _)) = joined {
                output.zeroize();
            }
            return Err(error);
        }
        let (mut output, admission) = joined?;
        let mut client = match Self::live_client(&self.state).await {
            Ok(client) => client,
            Err(error) => {
                output.zeroize();
                return Err(error);
            }
        };
        if let Err(error) = work_authority(&guard)
            .and_then(|_| admission.check(&client).map_err(BindingError::from))
            .and_then(|_| work_authority(&guard))
        {
            output.zeroize();
            return Err(error);
        }
        // This exact child remains registered until the locked final check.
        // Reset only our accepted completed call, synchronously before return.
        client.set_operation_cancel(CancellationToken::new());
        Ok(std::mem::take(&mut *output))
    }
}

