impl Monitor {
    fn valid(&self) -> Result<()> {
        self.guard.check()?;
        if !self.core.is_valid() {
            return Err(Error::Cancelled.into());
        }
        Ok(())
    }
    fn close(&self) {
        self.guard.cancel();
        self.core.close();
        if let Ok(mut pending) = self.refresh.lock() {
            pending.take();
        }
    }
}
