    ) -> Result<String> {
        scope(filters.personal, filters.team_id.as_deref())?;
        self.available()?;
        if filters.team_id.is_some() {
            return Err(Error::Unavailable {
                code: "workflow_unavailable",
                reason: "TEAM_WORKFLOW_OPERATION_UNAVAILABLE",
            }
            .into());
        }
        // Release only observers of this exact run before queuing its canonical
        // cancellation request. Other streams/CRUD operations keep their tokens.
        for wait in self
            .state
            .workflow_waits
            .lock()
            .map_err(|_| BindingError::from(Error::Protocol))?
            .values()
        {
            if wait.run == run {
                wait.cancel.cancel();
            }
        }
        self.work_transaction(Request::WorkflowCancelRun(id, run, filters))
            .await
    }
