    loop {
        match bridge.next_event_prepare(id.into()).await {
            Ok(output) => {
                let terminal = output.is_terminal();
                drop(output);
                if terminal {
                    return;
                }
            }
            Err(error) => {
                assert_eq!(error.code, "cancelled");
                return;
            }
        }
    }
